if (typeof window !== "undefined") window.LEETCODE_NUM_MAP = LEETCODE_NUM_MAP;
if (typeof globalThis !== "undefined") globalThis.LEETCODE_NUM_MAP = LEETCODE_NUM_MAP;

function getSlugFromUrl(url) {
  if (!url) return "";
  const match = url.match(/leetcode\.com\/problems\/([^\/\?#]+)/);
  return match ? match[1].toLowerCase() : "";
}

function getLeetCodeNumber(url) {
  const map = (typeof LEETCODE_NUM_MAP !== "undefined") ? LEETCODE_NUM_MAP : (typeof window !== "undefined" ? window.LEETCODE_NUM_MAP : null);
  if (!map || !url) return null;
  const slug = getSlugFromUrl(url);
  return slug ? (map[slug] || null) : null;
}

function parseLeetCodeNumberQuery(query) {
  if (!query) return null;
  const trimmed = query.trim();
  const match = trimmed.match(/^#?(\d+)$/);
  return match ? parseInt(match[1], 10) : null;
}

function getProblemNumber(p) {
  if (!p) return null;
  if (p.lcNum !== undefined && p.lcNum !== null) return p.lcNum;
  if (p.url) return getLeetCodeNumber(p.url);
  return null;
}

function getProblemNumberBadgeHtml(p) {
  const num = getProblemNumber(p);
  return num ? `<span class="lc-num">#${num}</span> ` : "";
}

if (typeof window !== "undefined") {
  window.getSlugFromUrl = getSlugFromUrl;
  window.getLeetCodeNumber = getLeetCodeNumber;
  window.parseLeetCodeNumberQuery = parseLeetCodeNumberQuery;
  window.getProblemNumber = getProblemNumber;
  window.getProblemNumberBadgeHtml = getProblemNumberBadgeHtml;
}
